/*
 * Button group and toolbar button styles. Generic token names map to the
 * Electron theme variables in app/globals.css:
 *   --color-text                          -> --ck-palette-ink
 *   --color-fill-primary-transparent-hover-> --ck-palette-surface-button-secondary-hover
 *   --color-text-strong-solid            -> --theme-background-control-opaque
 *   --color-panel                       -> --ck-palette-surface-surface
 *   --color-text-notice / --color-chart-blue-> --ck-palette-label-accent / --ck-palette-accent-blue
 *   --color-border(-subtle)               -> --ck-palette-border(-light)
 * `[data-state=open]` also matches Base UI's `[data-popup-open]`.
 */

@layer theme, base, components, utilities;

/* The component keeps these rules in `@layer components`, below utilities. */
@layer components {
  .button {
    position: relative;
    isolation: isolate;
    gap: calc(var(--spacing) * 2);
    border-radius: var(--radius-pill);
    border-width: 0;
    padding-inline: calc(var(--spacing) * 3);
    padding-block: 0;
    font-size: var(--text-sm);
    line-height: calc(var(--spacing) * 5);
    color: var(--ck-palette-ink);
  }

  .button::after {
    content: "";
    pointer-events: none;
    z-index: -10;
    border-radius: inherit;
    corner-shape: inherit;
    position: absolute;
    inset: 0;
  }

  .button:disabled {
    cursor: default;
  }

  .button.dropdown {
    gap: var(--spacing);
    padding-inline-end: calc(var(--spacing) * 1.5);
  }

  .button.zoom {
    gap: var(--spacing);
    padding-inline-start: calc(var(--spacing) * 2);
    padding-inline-end: var(--spacing);
  }

  @media (hover: hover) {
    .button:not(.selected, .primary):enabled:hover::after {
      background-color: var(--ck-palette-surface-button-secondary-hover);
    }
  }

  .button:not(.selected, .primary)[data-state="open"]::after,
  .button:not(.selected, .primary)[data-popup-open]::after {
    background-color: var(--ck-palette-surface-button-secondary-hover);
  }

  .button.primary {
    background-color: var(--ck-palette-ink);
    background-image: none;
    color: var(--theme-background-control-opaque);
  }

  @media (hover: hover) {
    .button.primary:enabled:hover {
      background-color: color-mix(
        in oklab,
        var(--ck-palette-ink) 82%,
        transparent
      );
    }
  }

  .button.primary[data-state="open"],
  .button.primary[data-popup-open] {
    background-color: color-mix(
      in oklab,
      var(--ck-palette-ink) 82%,
      transparent
    );
  }

  .button.selected {
    box-shadow: inset 0 0 0 0.5px
      color-mix(in srgb, var(--ck-palette-label-accent) 22%, transparent);
    background-image: none;
    background-color: color-mix(
      in srgb,
      var(--ck-palette-surface-surface) 92%,
      var(--ck-palette-accent-blue)
    );
    color: var(--ck-palette-label-accent);
  }

  .button.selected:enabled:hover:not([data-ck-hover-suppressed="true"]),
  .button.selected[data-state="open"],
  .button.selected[data-popup-open] {
    background-color: color-mix(
      in srgb,
      var(--ck-palette-surface-surface) 87%,
      var(--ck-palette-accent-blue)
    );
  }

  /* Dark text follows the nearest scope through light-dark. */
  .button.selected {
    --ck-viewer-selected-dark-text: color-mix(
      in srgb,
      var(--ck-palette-accent-blue),
      var(--ck-fixed-white)
        calc(
          20.4% + var(--ui-theme-contrast) * 0.31% +
            max(0, var(--ui-theme-contrast) - 58) * 0.31%
        )
    );
    color: light-dark(
      var(--ck-palette-label-accent),
      var(--ck-viewer-selected-dark-text, var(--ck-palette-label-accent))
    );
  }

  /*
   * Light draws a 1px light border and a soft drop shadow, dark draws two
   * half-pixel borders and a deeper shadow. Both lists share five layers so
   * light-dark picks the colors by the nearest scope.
   */
  .controlSurface {
    background: linear-gradient(
      light-dark(
        var(--ck-palette-surface-elevated-primary),
        var(--theme-background-control-opaque)
      ),
      light-dark(
        var(--ck-palette-surface-elevated-primary),
        var(--theme-background-control-opaque)
      )
    );
    box-shadow:
      0 0 0 1px light-dark(var(--ck-palette-border-light), transparent),
      0 0 0 0.5px light-dark(transparent, var(--ck-palette-border)),
      0 0 0 0.5px light-dark(transparent, var(--ck-palette-border)),
      0 3px 18px 0
        light-dark(
          color-mix(in srgb, var(--ck-shadow-color) 5%, transparent),
          transparent
        ),
      0 7px 18px -3px
        light-dark(
          transparent,
          color-mix(in srgb, var(--ck-shadow-color) 12%, transparent)
        );
    backdrop-filter: blur(22px);
  }

  .inputSurface {
    isolation: isolate;
    position: relative;
  }

  .inputSurface::after {
    content: "";
    pointer-events: none;
    z-index: -10;
    border-radius: var(--radius-pill);
    position: absolute;
    inset: 0;
  }

  .inputSurface:focus-within::after,
  .inputSurface:hover::after,
  .inputSurface[data-state="active"]::after {
    background-color: var(--ck-palette-surface-button-secondary-hover);
  }

  .capsule {
    padding: calc(var(--spacing) * 0.5);
  }

  .control {
    gap: var(--spacing);
    padding-inline: var(--spacing);
    padding-block: 0;
    font-size: var(--text-sm);
    line-height: calc(var(--spacing) * 5);
    height: calc(
      var(--ck-viewer-control-height, calc(var(--spacing) * 9)) - var(--spacing)
    );
  }

  .control:disabled {
    cursor: default;
  }

  .compound {
    border-radius: var(--radius-pill);
    color: var(--ck-palette-ink);
  }

  .compoundControl {
    height: 100%;
    padding-block: 0;
    font-size: var(--text-sm);
    line-height: calc(var(--spacing) * 5);
  }

  .compoundControl:disabled {
    cursor: default;
  }

  .button,
  .capsule,
  .compound,
  .title {
    height: var(--ck-viewer-control-height, calc(var(--spacing) * 9));
  }

  :is(
    [data-ck-viewer-density="compact"] .button,
    [data-ck-viewer-density="compact"] .capsule,
    [data-ck-viewer-density="compact"] .compound,
    [data-ck-viewer-density="compact"] .title
  ) {
    height: calc(var(--spacing) * 8);
  }

  [data-ck-viewer-density="compact"] .group {
    --ck-viewer-control-height: calc(var(--spacing) * 8);
  }

  .group {
    gap: calc(var(--spacing) * 0.5);
  }

  .group .button,
  .group .compound {
    border-width: 0;
    box-shadow: none;
    background-image: none;
    height: calc(
      var(--ck-viewer-control-height, calc(var(--spacing) * 9)) - var(--spacing)
    );
  }

  .group .button:not(.selected, .primary),
  .group .compound {
    background-color: transparent;
  }

  .group:has(
    > [role="group"]:not([data-ck-viewer-header-collapsed]) [data-ck-facepile]
  ) {
    gap: 0;
  }

  .group:has(
      > [role="group"]:not([data-ck-viewer-header-collapsed]) [data-ck-facepile]
    )
    .shareIcon {
    display: none;
  }

  :is(
    :is(.button, .control):has(
      [data-ck-viewer-compact-label="icon"][data-ck-viewer-header-collapsed]
    ),
    .button:has(> [data-ck-page-share-label][data-ck-viewer-header-collapsed])
  ) {
    aspect-ratio: 1;
    flex-shrink: 0;
    justify-content: center;
    padding-inline: 0;
  }

  :is(.button, .control):has(
    [data-ck-viewer-compact-label="content"][data-ck-viewer-header-collapsed]
  ) {
    padding-inline: calc(var(--spacing) * 2);
    flex-shrink: 0;
    justify-content: center;
  }

  .divider {
    height: calc(var(--spacing) * 4);
    background-color: var(--ck-palette-border);
    flex-shrink: 0;
    width: 1px;
  }

  :where([data-ck-viewer-density="regular"]) .divider {
    margin-inline: calc(var(--spacing) * 0.5);
  }

  .joined .divider {
    margin-inline: var(--spacing);
  }

  .zoomGroup .divider {
    margin-inline: calc(var(--spacing) * 0.5);
  }

  :where([data-ck-viewer-density="regular"]) .zoomGroup .divider {
    margin-inline: var(--spacing);
  }

  .divider.sectionDivider {
    margin-inline: calc(var(--spacing) * 1.5);
  }

  .joined .button {
    padding-inline: var(--spacing);
  }

  .joined .button:first-child {
    padding-inline-start: calc(var(--spacing) * 3);
  }

  .joined .button:last-child {
    padding-inline-end: calc(var(--spacing) * 3);
  }

  .joined .button:last-child:not(:first-child, .label) {
    margin-inline-end: calc(var(--spacing) * 2);
    padding-inline-end: var(--spacing);
  }

  .joined .button.label {
    padding-inline: calc(var(--spacing) * 3);
  }

  .joined .button.avatarGroup {
    padding-inline-start: calc(var(--spacing) * 0.5);
    padding-inline-end: 0;
  }

  .joined .button.avatarGroup:last-child {
    padding-inline-end: calc(var(--spacing) * 0.5);
  }

  .group [data-ck-header-action] {
    height: calc(
      var(--ck-viewer-control-height, calc(var(--spacing) * 9)) - var(--spacing)
    ) !important;
    min-width: calc(
      var(--ck-viewer-control-height, calc(var(--spacing) * 9)) - var(--spacing)
    ) !important;
  }

  .group [data-ck-header-action]:not([data-ck-has-label]) {
    width: calc(
      var(--ck-viewer-control-height, calc(var(--spacing) * 9)) - var(--spacing)
    ) !important;
    max-width: calc(
      var(--ck-viewer-control-height, calc(var(--spacing) * 9)) - var(--spacing)
    ) !important;
  }

  [data-ck-viewer-density="compact"] .group [data-ck-header-action] {
    height: calc(var(--spacing) * 7) !important;
    min-width: calc(var(--spacing) * 7) !important;
  }

  [data-ck-viewer-density="compact"]
    .group
    [data-ck-header-action]:not([data-ck-has-label]) {
    width: calc(var(--spacing) * 7) !important;
    max-width: calc(var(--spacing) * 7) !important;
  }

  :is(
    [data-ck-viewer-density="compact"] .group :where(.button, .compound),
    [data-ck-viewer-density="compact"] .control
  ) {
    height: calc(var(--spacing) * 7);
  }

  .capsule.group:has(
      > :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    ):not(
      :has(
        > :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
          ~ :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
      )
    ):not(
      :has(
        > [role="group"]:not(
          [data-ck-viewer-header-collapsed],
          [hidden],
          .sr-only
        )
      )
    ) {
    padding: 0;
  }

  .capsule.group
    > :not([role="group"]):nth-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    ):nth-last-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    ):is(button),
  .capsule.group
    > :not([role="group"]):nth-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    ):nth-last-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    )
    > button:only-child {
    height: 100%;
  }

  .capsule.group
    > :not([role="group"]):nth-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    ):nth-last-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    ):has(> :is(button, [data-ck-header-action]):only-child) {
    height: 100%;
  }

  .capsule.group
    > :not([role="group"]):nth-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    ):nth-last-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    )[data-ck-header-action],
  .capsule.group
    > :not([role="group"]):nth-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    ):nth-last-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    )
    > [data-ck-header-action]:only-child {
    height: 100% !important;
  }

  .capsule.group
    > :not([role="group"]):nth-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    ):nth-last-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    )[data-ck-header-action]:not([data-ck-has-label]),
  .capsule.group
    > :not([role="group"]):nth-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    ):nth-last-child(
      1 of :not([data-ck-viewer-header-collapsed], [hidden], .sr-only)
    )
    > [data-ck-header-action]:only-child:not([data-ck-has-label]) {
    width: var(--ck-viewer-control-height, calc(var(--spacing) * 9)) !important;
    min-width: var(
      --ck-viewer-control-height,
      calc(var(--spacing) * 9)
    ) !important;
    max-width: var(
      --ck-viewer-control-height,
      calc(var(--spacing) * 9)
    ) !important;
  }
}

"use client";

/* oxlint-disable shadcn/no-restyle, shadcn/require-static-classes -- ToolbarButton and RoundIconToggleButton are the button family's own composites: the component builds them from ButtonBase with the group module's classes. */

import { Tooltip } from "@base-ui/react/tooltip";
import { ButtonBase } from "@/components/ui/button";
import type {
  ButtonColor,
  ButtonProps,
} from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { ComponentProps, ReactNode } from "react";

import styles from "./button-group.module.css";

// ButtonGroup and its capsule, ToolbarButton, RoundIconToggleButton, the
// divider and the title pill. Their classes come from button-group.module.css.

export type ButtonGroupVariant = "default" | "joined" | "zoom";

interface ControlCapsuleProps extends ComponentProps<"div"> {
  variant?: "default" | "input";
}

const ControlCapsule = ({
  className,
  variant = "default",
  ...props
}: ControlCapsuleProps) => (
  <div
    className={cn(
      styles.capsule,
      styles.controlSurface,
      variant === "input" && styles.inputSurface,
      "rounded-full",
      className
    )}
    data-ck-menu-overlay-surface
    {...props}
  />
);

export interface ButtonGroupProps extends Omit<
  ComponentProps<"div">,
  "aria-label"
> {
  /** Accessible name of the group. */
  label?: string;
  /** Hides the group when it has no children. */
  hideWhenEmpty?: boolean;
  /** Lets the group shrink instead of keeping its width. */
  shrink?: boolean;
  variant?: ButtonGroupVariant;
}

/** A `role="group"` that lays its buttons out in one capsule. */
export const ButtonGroup = ({
  children,
  className,
  hideWhenEmpty = false,
  label,
  shrink = false,
  variant = "default",
  ...props
}: ButtonGroupProps) => (
  <ControlCapsule
    {...props}
    aria-label={label}
    className={cn(
      styles.group,
      variant === "joined" && styles.joined,
      variant === "zoom" && styles.zoomGroup,
      hideWhenEmpty && "empty:hidden",
      "inline-flex items-center border-0 text-text",
      shrink ? "min-w-0" : "shrink-0",
      (variant === "joined" || variant === "zoom") && "gap-0",
      className
    )}
    // oxlint-disable-next-line jsx-a11y/prefer-tag-over-role -- the component renders a div with role="group" and an aria-label.
    role="group"
  >
    {children}
  </ControlCapsule>
);

export type ToolbarButtonVariant =
  | "avatarGroup"
  | "default"
  | "dropdown"
  | "ghost"
  | "label"
  | "primary"
  | "selected"
  | "zoom";

export interface ToolbarButtonProps extends ButtonProps {
  /** Applies the selected surface. */
  selected?: boolean;
  variant?: ToolbarButtonVariant;
}

/** A button in a group or toolbar: unstyled ButtonBase plus the group look. */
export const ToolbarButton = ({
  className,
  selected = false,
  uniform,
  variant = "default",
  ...props
}: ToolbarButtonProps) => (
  <ButtonBase
    {...props}
    className={cn(
      styles.button,
      variant !== "ghost" && styles.controlSurface,
      variant === "primary" && styles.primary,
      (selected || variant === "selected") && styles.selected,
      (variant === "dropdown" || variant === "zoom") && styles.dropdown,
      variant === "zoom" && styles.zoom,
      variant === "label" && styles.label,
      variant === "avatarGroup" && styles.avatarGroup,
      variant !== "primary" &&
        "disabled:text-text-subtle disabled:opacity-100 aria-disabled:text-text-subtle aria-disabled:opacity-100",
      className
    )}
    uniform={uniform}
    unstyled
  />
);

export interface RoundIconToggleButtonProps extends ButtonProps {
  color?: ButtonColor;
}

/** A round, uniform, ghost button for icon toggles. */
export const RoundIconToggleButton = ({
  className,
  color = "ghostActive",
  ...props
}: RoundIconToggleButtonProps) => (
  <ButtonBase
    {...props}
    className={cn(styles.control, className)}
    color={color}
    radius="full"
  />
);

export interface ButtonGroupDividerProps {
  /** `section` draws the wider-spaced divider between sections. */
  variant?: "default" | "section";
}

/** A 1px vertical rule between buttons. Hidden from assistive technology. */
export const ButtonGroupDivider = ({
  variant = "default",
}: ButtonGroupDividerProps) => (
  <span
    aria-hidden="true"
    className={cn(
      styles.divider,
      variant === "section" && styles.sectionDivider
    )}
  />
);

export interface ButtonGroupTitleProps {
  icon?: ReactNode;
  /** Shows the full title in a tooltip. */
  showTooltip?: boolean;
  title: ReactNode;
}

/** A pill showing a title that truncates at 168px. */
export const ButtonGroupTitle = ({
  icon,
  showTooltip = true,
  title,
}: ButtonGroupTitleProps) => {
  const pill = (
    <div
      className={cn(
        styles.title,
        styles.controlSurface,
        "inline-flex min-w-0 items-center gap-2 rounded-full border-0 px-3 text-sm text-text"
      )}
    >
      {icon}
      <span
        className="block max-w-[168px] min-w-0 truncate"
        data-ck-viewer-header-collapsible={
          icon === undefined || icon === null ? undefined : true
        }
      >
        {title}
      </span>
    </div>
  );

  if (!showTooltip) {
    return pill;
  }

  // The tooltip: opens after 150ms or on keyboard focus, is not
  // hoverable, closes on click, pointer leave, blur and Escape (Escape does
  // not reach outer handlers), sits 5px below the trigger with 15px of
  // collision padding, is at most min(320px, the available width) wide and is
  // hidden once its trigger is scrolled out of view.
  return (
    <Tooltip.Root
      disableHoverablePopup
      onOpenChange={(_open, details) => {
        if (details.reason === "escape-key") {
          details.event.stopPropagation();
        }
      }}
    >
      <Tooltip.Trigger closeDelay={0} closeOnClick delay={150} render={pill} />
      <Tooltip.Portal>
        <Tooltip.Positioner
          className="z-50 data-anchor-hidden:invisible"
          collisionPadding={15}
          side="bottom"
          sideOffset={5}
        >
          <Tooltip.Popup
            className="tooltip-popup max-w-[min(320px,var(--available-width))] text-center wrap-break-word whitespace-normal"
            role="tooltip"
          >
            {title}
          </Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
};

/*
 * Data-attribute Button styles: the button with its inner and loader parts,
 * the loading indicator and the transition group child.
 *
 * The component reads its colors, sizes and gutters from theme tokens. The token
 * block below resolves every token this module uses for the Electron theme:
 * the base theme rules, the non-extension app color rules
 * and the Electron block. Values that
 * differ between light and dark use light-dark, so they follow the nearest
 * color-scheme scope. App colors come from the foundations theme variables.
 * `[data-state=open]` also matches Base UI's `[data-popup-open]`.
 */

@layer theme, base, components, utilities;

@layer components {
  .button {
    --ck-action-corner-scale: 1;
    --ck-action-gap-sm: 3px;
    --ck-action-gap-md: 4px;
    --ck-action-gap-lg: 6px;
    --ck-action-font-weight: 400;
    --ck-action-surface-border-color: color-mix(
      in srgb,
      var(--ck-shadow-color) 4%,
      transparent
    );

    /* Control scale. */
    --ck-control-font-size-lg: 1rem;
    --ck-control-font-size-md: 0.875rem;
    --ck-control-font-size-sm: 0.75rem;
    --ck-control-gutter-2xs: 0.375rem;
    --ck-control-gutter-lg: 0.875rem;
    --ck-control-gutter-md: 0.75rem;
    --ck-control-gutter-pill-scaling: 1.3;
    --ck-control-gutter-sm: 0.625rem;
    --ck-control-gutter-xl: 1rem;
    --ck-control-gutter-xs: 0.5rem;
    --ck-control-icon-size-2xl: 1.5rem;
    --ck-control-icon-size-lg: 1.25rem;
    --ck-control-icon-size-md: 1.125rem;
    --ck-control-icon-size-sm: 1rem;
    --ck-control-icon-size-xl: 1.375rem;
    --ck-control-icon-size-xs: 0.875rem;
    --ck-control-radius-lg: calc(0.625rem * var(--ck-action-corner-scale));
    --ck-control-radius-md: calc(0.5rem * var(--ck-action-corner-scale));
    --ck-control-radius-sm: calc(0.375rem * var(--ck-action-corner-scale));
    --ck-control-radius-xl: calc(0.75rem * var(--ck-action-corner-scale));
    --ck-control-size-2xl: 2.75rem;
    --ck-control-size-2xs: 1.5rem;
    --ck-control-size-3xl: 3rem;
    --ck-control-size-3xs: 1.375rem;
    --ck-control-size-4xs: 1.25rem;
    --ck-control-size-lg: 2.25rem;
    --ck-control-size-md: 2rem;
    --ck-control-size-sm: 1.75rem;
    --ck-control-size-xl: 2.5rem;
    --ck-control-size-xs: 1.625rem;
    --radius-pill: 9999px;
    --motion-duration-fast: 0.16s;
    --ck-motion-ease-basic: ease;

    /* Theme colors resolved for the Electron light and dark themes. */
    --color-fill-caution-transparent-pressed: color-mix(
      in oklab,
      var(--color-status-caution-fill) 15%,
      transparent
    );
    --color-fill-caution-transparent-hover: color-mix(
      in oklab,
      var(--color-status-caution-fill) 15%,
      transparent
    );
