  @supports (corner-shape: superellipse(1.6)) {
    .button {
      --ck-action-corner-scale: 1.2;
    }
  }

  .button {
    gap: var(--ck-action-gap);
    height: var(--ck-action-size);
    padding: 0 var(--ck-action-gutter);
    border-radius: var(--ck-action-radius);
    -webkit-app-region: no-drag;
    cursor: var(--ck-action-cursor, pointer);
    font-size: var(--ck-action-font-size);
    font-weight: var(--ck-action-font-weight);
    transition-duration: var(--motion-duration-fast);
    transition-property: opacity, color;
    transition-timing-function: var(--ck-motion-ease-basic);
    -webkit-user-select: none;
    user-select: none;
    white-space: nowrap;
    flex-shrink: 0;
    line-height: 1;
    display: inline-block;
    position: relative;
  }

  .button:before {
    border-radius: inherit;
    content: "";
    corner-shape: inherit;
    transition-duration: var(--motion-duration-fast);
    transition-property:
      opacity, background-color, transform, box-shadow, border-color;
    transition-timing-function: var(--ck-motion-ease-basic);
    will-change: transform;
    display: block;
    position: absolute;
    inset: 0;
  }

  .button:after {
    border-radius: inherit;
    content: "";
    corner-shape: inherit;
    pointer-events: none;
    transition-duration: var(--motion-duration-fast);
    transition-property: transform;
    transition-timing-function: var(--ck-motion-ease-basic);
    will-change: transform;
    display: block;
    position: absolute;
    inset: 0;
  }

  .button:focus {
    outline: none;
  }

  .button:focus-visible:after {
    outline: 2px solid var(--ck-action-ring-color, var(--color-ring));
    outline-offset: var(--ck-action-ring-offset, 2px);
  }

  .button svg:where(:not([data-ck-no-autosize])) {
    width: var(--ck-action-icon-size);
    height: var(--ck-action-icon-size);
  }

  :where(
    .button svg:where(:not([data-ck-no-autosize])):first-child:not(:only-child)
  ) {
    margin-left: var(--ck-action-icon-offset, -1px);
  }

  :where(
    .button svg:where(:not([data-ck-no-autosize])):last-child:not(:only-child)
  ) {
    margin-right: var(--ck-action-icon-offset, -1px);
  }

  .button:where([data-ck-optically-align="start"]) {
    margin-inline-start: calc(var(--ck-action-gutter) * -1);
  }

  .button:where([data-ck-optically-align="start"][data-pill]) {
    margin-inline-start: calc(
      var(--ck-action-gutter) * var(--ck-control-gutter-pill-scaling) * -1
    );
  }

  .button:where([data-ck-optically-align="end"]) {
    margin-inline-end: calc(var(--ck-action-gutter) * -1);
  }

  .button:where([data-ck-optically-align="end"][data-pill]) {
    margin-inline-end: calc(
      var(--ck-action-gutter) * var(--ck-control-gutter-pill-scaling) * -1
    );
  }

  .button:where([data-ck-optically-align="start"][data-uniform]) {
    margin-inline-start: calc(
      ((var(--ck-action-size) - var(--ck-action-icon-size)) / 2) * -1
    );
  }

  .button:where([data-ck-optically-align="end"][data-uniform]) {
    margin-inline-end: calc(
      ((var(--ck-action-size) - var(--ck-action-icon-size)) / 2) * -1
    );
  }

  .button:where([data-size="3xs"]) {
    --ck-action-size: var(--ck-control-size-4xs);
    --ck-action-gutter: var(--ck-control-gutter-2xs);
    --ck-action-font-size: var(--ck-control-font-size-sm);
    --ck-action-icon-size: var(--ck-control-icon-size-xs);
    --ck-action-gap: var(--ck-action-gap-sm);
    --ck-action-radius: var(--ck-control-radius-sm);
    --ck-action-icon-offset: -1px;
    --progress-ring-size: 11px;
    --ck-progress-diameter: 11px;
